import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { DEFAULT_LANG, isLang, normalize } from './languages';

// Site-wide translation.
//  • English is the source text. Other languages live in src/i18n/dist/<lang>.json
//    (generated by `npm run i18n` from src/i18n/parts/*.js — hand-written, meaning-first).
//  • `t(text)` translates a string in React code (headlines, SEO, chat).
//  • A MutationObserver translates every other piece of rendered text (and alt / aria-label /
//    placeholder / title) by exact match, remembering the English original so switching
//    languages — or back to English — always starts from the source text.

const LangContext = createContext({ lang: DEFAULT_LANG, setLang: () => {}, t: (s) => s });
export const useLang = () => useContext(LangContext);

const loaders = {
  es: () => import('./dist/es.json'),
  fr: () => import('./dist/fr.json'),
  ru: () => import('./dist/ru.json'),
  zh: () => import('./dist/zh.json'),
  de: () => import('./dist/de.json'),
};
const cache = {};

const ATTRS = ['aria-label', 'alt', 'placeholder', 'title'];
const SKIP = 'script,style,noscript,textarea,.reveal-text,[translate="no"],.notranslate';

function readStored() {
  try {
    const q = new URLSearchParams(window.location.search).get('lang');
    if (q && isLang(q)) return q;
    const s = window.localStorage.getItem('nuvo-lang');
    if (s && isLang(s)) return s;
  } catch {
    /* storage unavailable */
  }
  return DEFAULT_LANG;
}

export function LangProvider({ children }) {
  const [lang, setLangState] = useState(readStored);
  const [dict, setDict] = useState(null); // translations for the current language
  const dictRef = useRef(null);
  const texts = useRef(new WeakMap());
  const attrs = useRef(new WeakMap());

  const setLang = useCallback((code) => {
    if (!isLang(code)) return;
    setLangState(code);
    try {
      window.localStorage.setItem('nuvo-lang', code);
    } catch {
      /* ignore */
    }
  }, []);

  // load the language file
  useEffect(() => {
    document.documentElement.lang = lang;
    if (lang === DEFAULT_LANG) {
      dictRef.current = null;
      setDict(null);
      return undefined;
    }
    let cancelled = false;
    const get = cache[lang] ? Promise.resolve(cache[lang]) : loaders[lang]().then((m) => (cache[lang] = m.default || m));
    get.then((d) => {
      if (!cancelled) {
        dictRef.current = d;
        setDict(d);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [lang]);

  const translate = useCallback((s) => {
    const d = dictRef.current;
    if (!d || typeof s !== 'string') return s;
    const lead = s.match(/^\s*/)[0];
    const trail = s.match(/\s*$/)[0];
    const hit = d[normalize(s)];
    return hit ? lead + hit + trail : s;
  }, []);

  const t = useMemo(
    () => (s) => {
      if (typeof s === 'string' && window.__I18N_COLLECT) window.__I18N_COLLECT.add(normalize(s)); // string extraction (scripts/extract-i18n.mjs)
      return dict && typeof s === 'string' ? (dict[normalize(s)] ?? s) : s;
    },
    [dict]
  );

  // DOM translator
  useEffect(() => {
    const root = document.getElementById('root');
    if (!root) return undefined;

    const skipped = (el) => !el || !!el.closest?.(SKIP);

    const doText = (node) => {
      if (skipped(node.parentElement)) return;
      const rec = texts.current.get(node);
      if (rec && node.nodeValue === rec.applied) return;
      const orig = node.nodeValue;
      if (!orig.trim()) return;
      const out = translate(orig);
      if (out !== orig) {
        node.nodeValue = out;
        texts.current.set(node, { orig, applied: out });
      } else texts.current.delete(node);
    };

    const doAttrs = (el) => {
      if (skipped(el)) return;
      let rec = attrs.current.get(el);
      for (const a of ATTRS) {
        const cur = el.getAttribute?.(a);
        if (cur == null) continue;
        const r = rec?.[a];
        if (r && cur === r.applied) continue;
        const out = translate(cur);
        if (out !== cur) {
          el.setAttribute(a, out);
          if (!rec) attrs.current.set(el, (rec = {}));
          rec[a] = { orig: cur, applied: out };
        } else if (rec) delete rec[a];
      }
    };

    const walk = (node) => {
      if (node.nodeType === 3) return doText(node);
      if (node.nodeType !== 1 || skipped(node)) return undefined;
      doAttrs(node);
      const tw = document.createTreeWalker(node, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
      let n = tw.nextNode();
      while (n) {
        if (n.nodeType === 3) doText(n);
        else doAttrs(n);
        n = tw.nextNode();
      }
      return undefined;
    };

    // Put the stored English originals back (language switch / back to English).
    const restore = () => {
      const tw = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
      let n = tw.nextNode();
      while (n) {
        if (n.nodeType === 3) {
          const rec = texts.current.get(n);
          if (rec && n.nodeValue === rec.applied) {
            n.nodeValue = rec.orig;
            texts.current.delete(n);
          }
        } else {
          const rec = attrs.current.get(n);
          if (rec) {
            for (const a of Object.keys(rec)) if (n.getAttribute(a) === rec[a].applied) n.setAttribute(a, rec[a].orig);
            attrs.current.delete(n);
          }
        }
        n = tw.nextNode();
      }
    };

    restore();
    if (!dictRef.current) return undefined;
    walk(root);

    const mo = new MutationObserver((muts) => {
      for (const m of muts) {
        if (m.type === 'characterData') doText(m.target);
        else if (m.type === 'attributes') doAttrs(m.target);
        else m.addedNodes.forEach(walk);
      }
    });
    mo.observe(root, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRS });
    return () => mo.disconnect();
  }, [dict, translate]);

  const value = useMemo(() => ({ lang, setLang, t }), [lang, setLang, t]);
  return <LangContext.Provider value={value}>{children}</LangContext.Provider>;
}
